#include <stdio.h>
#include <string.h>
int main(){
    char s[20];
    scanf("%19s", s);
    int state = 0;
    for(int i=0; s[i]; ++i){
        char c = s[i];
        if(state==0){
            if(c>='6' && c<='9') state=1; else {state=-1; break;}
        } else if(state>=1 && state<=9){
            if(c>='0' && c<='9') state++; else {state=-1; break;}
        }
    }
    if(state==10) printf("Accepted\n"); else printf("Rejected\n");
    return 0;
}

